    ListNode* reverseList(ListNode* head) {
        vector<int> values;
        for (ListNode* curr = head; curr != nullptr; curr = curr->next) values.push_back(curr->val);
        for (ListNode* curr = head; curr != nullptr; curr = curr->next) {
